import itertools, random
from solvers import three_coloring_solve, one_in_three_solve

def naive_3col(inst):
    n, edges = inst["n"], inst["edges"]
    for col in itertools.product(range(3), repeat=n):
        if all(col[u] != col[v] for u, v in edges):
            return True
    return False

def naive_1in3(inst):
    m, clauses = inst["num_vars"], inst["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        if all(sum(bits[x-1] for x in cl) == 1 for cl in clauses):
            return True
    return False

rng = random.Random(7)
# verify 3col solver
for _ in range(2000):
    n = rng.randint(0, 6)
    edges = [[u,v] for u in range(n) for v in range(u+1,n) if rng.random()<0.5]
    inst = {"n": n, "edges": edges}
    assert three_coloring_solve(inst) == naive_3col(inst), inst
# verify 1in3 solver on random formulas
for _ in range(2000):
    m = rng.randint(0, 7)
    clauses = []
    for _ in range(rng.randint(0, 6)):
        if m < 3: break
        clauses.append(rng.sample(range(1, m+1), 3))
    inst = {"num_vars": m, "clauses": clauses}
    assert one_in_three_solve(inst) == naive_1in3(inst), inst
print("solvers verified OK")
EOF
python3 verify_solvers.py"}

